code_example:
std::vector<int> source = {10, 20, 30};
std::list<int> destination;

// std::front_inserter requires push_front() (list, deque)
// It wraps push_front(), inserting elements at the beginning.
// Order of insertion is reversed relative to the source range.
std::copy(source.begin(), source.end(),
          std::front_inserter(destination));

// destination contents: {30, 20, 10} (Efficient O(1) per insert)
// Cannot be used with std::vector (no push_front)
// Use std::back_inserter for normal vector insertion (push_back)
